// Research harness: reuse unmodified production FBI/Hermite kernels.
#include "../../../src/IBP/kernel/point.cpp"
json load_json(const std::string&path){std::ifstream f(path);if(!f)throw std::runtime_error("cannot open "+path);json j;f>>j;return j;}
void save_json(const std::string&path,const json&j){std::ofstream f(path);if(!f)throw std::runtime_error("cannot write "+path);f<<j.dump()<<'\n';}
std::string specialize_text(const json&v,const json&parameters){if(!parameters.empty())throw std::runtime_error("snapshot requires fully numerical exact input");if(v.is_string())return v.get<std::string>();if(v.is_number_integer())return v.dump();throw std::runtime_error("exact scalar required");}
Nu parse_label(const std::string&s,int n){auto a=s.find('{'),b=s.find('}');if(a==std::string::npos||b==std::string::npos)throw std::runtime_error("invalid object name");auto v=json::parse("["+s.substr(a+1,b-a-1)+"]").get<Nu>();if(int(v.size())!=n)throw std::runtime_error("object dimension mismatch");return v;}
json record(const ZR&v){return {{"n",polyjson(v.n)},{"d",polyjson(v.d)}};}
ZR readzr(const json&j){P n,d;for(size_t k=0;k<j.at("n").size();++k)n.set(k,j["n"][k].get<U>());for(size_t k=0;k<j.at("d").size();++k)d.set(k,j["d"][k].get<U>());return ZR(n,d);}
std::vector<ZR> readrow(const json&j){std::vector<ZR>v;for(auto&x:j)v.push_back(readzr(x));return v;}
json rowrecord(const std::vector<ZR>&v){json a=json::array();for(auto&x:v)a.push_back(record(x));return a;}
void init(U p){prime=p;nmod_init(&mod,p);nmod_mpoly_ctx_init(mc,2,ORD_LEX,p);}
json native_config(const json&req){auto f=req.at("family"),point=req.at("point"),j=req.at("j");json pars=point.value("parameters",json::object());json cfg={{"kind","two_loop_family"},{"prime",point["prime"]},{"dimension",specialize_text(point["dimension"],pars)},{"specialize_t",specialize_text(point["t"],pars)},{"gram",json::array()},{"propagators",f["propagators"]},{"canonical_fbi_symmetries",true},{"targets",req["request"]["targets"]}};
 for(auto&row:f["gram"]){json v=json::array();for(auto&x:row)v.push_back(specialize_text(x,pars));cfg["gram"].push_back(v);}
 for(size_t i=0;i<cfg["propagators"].size();++i){auto&p=cfg["propagators"][i];p["branch"]=j["branches"][i];for(auto&x:p["loop"])x=specialize_text(x,pars);for(auto&x:p["shift"])x=specialize_text(x,pars);p["mass2"]=specialize_text(p["mass2"],pars);}
 std::set<Nu>parents;for(auto&v:cfg["targets"])parents.insert(v.get<Nu>());if(req["request"].contains("basis"))for(auto&v:req["request"]["basis"])parents.insert(parse_label(v.get<std::string>(),cfg["propagators"].size()));cfg["targets"]=json::array();for(auto&v:parents)cfg["targets"].push_back(v);return cfg;
}
void snapshot(const std::string&input,const std::string&output){auto req=load_json(input);if(req["j"].contains("cut_sector")||req["j"]["boundary"]["z0"]!="fbi_analytic")throw std::runtime_error("this experiment requires the global physical FBI endpoint");init(req["point"]["prime"]);auto cfg=native_config(req);auto start=Clock::now();NativeFamily family(cfg);RMat At,Az;std::map<std::string,RRow>raw;family.model(At,Az,raw);
 json out={{"source",input},{"prime",prime},{"point",req["point"]},{"masters",family.masters},{"connection",json::array()},{"rows",json::object()},{"targets",req["request"]["targets"]},{"basis",req["request"].value("basis",json::array())},{"boundary",req["j"]["boundary"]},{"orders",json::array()},{"aliases",family.endpoint_corner_aliases()}};
 std::vector<std::vector<ZR>>az;for(auto&v:Az)az.push_back(asz(v));TriangularIntegrator reference(az,16);out["reference_seeds"]=json::array();for(int i=0;i<family.rank;++i){auto save=[&](const ZR&g){std::vector<ZR>v(family.rank);v[i]=g;out["reference_seeds"].push_back(rowrecord(v));};auto&a=*reference.scalar[i];for(auto&[f,k]:reference.factors.get(a.A.d)){P res=a.residue(f),df=derivative(f);for(int n=2;n<=17;++n)if(modp(res-scale(df,n-1),f).zero())for(int j=0;j<f.deg();++j){P p;p.set(j,1);save(ZR(p,ppow(f,n-1)));}}U lambda=a.A.n.deg()+1==a.A.d.deg()?nmod_div(a.A.n.at(a.A.n.deg()),a.A.d.at(a.A.d.deg()),mod):0;for(int n=0;n<=16;++n)if(add(U(n),lambda)==0){P p;p.set(n,1);save(zp(p));}}
 for(auto&v:Az)out["connection"].push_back(rowrecord(asz(v)));for(auto&[name,row]:raw)out["rows"][name]=rowrecord(asz(row));for(auto&nu:family.masters){int order=-1;for(int i=0;i<family.n;++i)if(family.branch[i]==2)order+=nu[i];out["orders"].push_back(order);}Quotient physical;std::vector<int>orders=out["orders"].get<std::vector<int>>();for(int i=0;i<family.rank;++i)for(auto&[n,logs]:reference.endpoint.jets[i])for(size_t l=0;l<logs.size();++l)if(l||n<orders[i])physical.insert(logs[l]);for(auto&ij:out["aliases"]){C c=reference.endpoint.finite_part(ij[0],ZR(1));axpy(c,reference.endpoint.finite_part(ij[1],ZR(1)),prime-1);physical.insert(std::move(c));}out["z0_physical_jets"]=json::array();for(int n=0;n<=16;++n){json row=json::array();for(int i=0;i<family.rank;++i){auto it=reference.endpoint.jets[i].find(n);C c;if(it!=reference.endpoint.jets[i].end()&&!it->second.empty())c=physical.reduce(it->second[0]);row.push_back(c);}out["z0_physical_jets"].push_back(row);}out["z0_physical_constraints_rank"]=physical.rows.size();out["model_seconds"]=seconds(start);save_json(output,out);std::cerr<<"snapshot rank="<<family.rank<<" rows="<<raw.size()<<" seconds="<<seconds(start)<<"\n";
}
void reduce_snapshot(const std::string&input,const std::string&output,const std::string&seeds){auto cfg=load_json(input);init(cfg["prime"]);auto start=Clock::now();std::vector<std::vector<ZR>>A;for(auto&v:cfg["connection"])A.push_back(readrow(v));TriangularIntegrator integrator(A,16);int submitted_seeds=0;
 if(seeds=="reference")integrator.complete(16);
 else{auto s=load_json(seeds);for(auto&gjson:s.at("rows")){auto g=readrow(gjson);std::vector<ZR>v(A.size());C boundary;for(size_t i=0;i<A.size();++i){v[i]=v[i]+g[i].diff();if(g[i].zero())continue;axpy(boundary,integrator.endpoint.finite_part(i,g[i]),1);for(size_t j=i;j<A.size();++j)if(!A[i][j].zero())v[j]=v[j]+g[i]*A[i][j];}C relation=integrator.raw(std::move(v));axpy(relation,boundary,1);integrator.completion.insert(std::move(relation));++submitted_seeds;}}
 if(cfg["boundary"]["z0"]=="fbi_analytic"){integrator.impose_analytic_boundary(cfg["orders"].get<std::vector<int>>());for(auto&ij:cfg["aliases"]){int i=ij[0],j=ij[1];C relation=integrator.endpoint.finite_part(i,ZR(1));axpy(relation,integrator.endpoint.finite_part(j,ZR(1)),prime-1);integrator.completion.insert(std::move(relation));}}
 auto relation_seconds=seconds(start);std::map<std::string,C>coords;for(auto it=cfg["rows"].begin();it!=cfg["rows"].end();++it)coords[it.key()]=integrator.integrate(readrow(it.value()));for(size_t i=0;i<A.size();++i){std::string name="Bz0"+label(cfg["masters"][i].get<Nu>()).substr(1);C c=integrator.endpoint.finite_part(i,ZR(1));coords[name]=integrator.completion.reduce(std::move(c));}
 std::vector<std::string>basis=cfg["basis"].get<std::vector<std::string>>();if(basis.empty())throw std::runtime_error("experiment needs a fixed physical J basis");Span span;for(int i=0;i<int(basis.size());++i){auto&name=basis[i];if(!coords.count(name)&&name.rfind("Bz",0)==0){auto row=readrow(cfg["rows"].at(parent_j(name)));coords[name]=integrator.boundary(row,name[2]-'0');}if(!span.insert(coords.at(name),i))throw std::runtime_error("physical basis became dependent");}
 json values=json::object(),unresolved=json::array();for(auto&nu:cfg["targets"]){std::string name=label(nu.get<Nu>());try{auto v=span.solve(coords.at(name),basis.size());json row=json::object();for(size_t i=0;i<v.size();++i)if(v[i])row[basis[i]]=v[i];values[name]=row;}catch(const std::exception&){unresolved.push_back(name);}}
 std::set<std::string>columns;for(auto&[name,c]:coords)for(auto&kv:c)columns.insert(kv.first);json out={{"seed_source",seeds},{"submitted_primitive_seeds",submitted_seeds},{"z_nonzero_rows",integrator.completion.nonzero_rows},{"z_independent_rows",integrator.completion.rows.size()},{"z_columns",integrator.completion.submitted_columns.size()},{"z_nnz",integrator.completion.submitted_nonzeros},{"target_coordinate_columns",columns.size()},{"unresolved",unresolved},{"basis",basis},{"reductions",values},{"relation_seconds",relation_seconds},{"total_seconds",seconds(start)}};save_json(output,out);std::cerr<<"seeds="<<seeds<<" rank="<<integrator.completion.rows.size()<<" unresolved="<<unresolved.size()<<" seconds="<<seconds(start)<<"\n";
}

void image_reduce(const std::string&input,const std::string&output,const std::string&seeds){
 auto cfg=load_json(input);init(cfg["prime"]);auto start=Clock::now();std::vector<std::vector<ZR>>A;for(auto&v:cfg["connection"])A.push_back(readrow(v));int r=A.size();TriangularIntegrator integrator(A,16);
 integrator.impose_analytic_boundary(cfg["orders"].get<std::vector<int>>());for(auto&ij:cfg["aliases"]){C c=integrator.endpoint.finite_part(ij[0],ZR(1));axpy(c,integrator.endpoint.finite_part(ij[1],ZR(1)),prime-1);integrator.completion.insert(std::move(c));}
 auto physical=integrator.completion;integrator.completion=Quotient();Span image;int density_generators=0;
 auto raw_image=[&](const std::vector<ZR>&v){return physical.reduce(integrator.raw(v));};
 auto seed_data=load_json(seeds);for(auto&row:seed_data["rows"]){auto c=raw_image(readrow(row));image.insert(std::move(c),image.rows.size());++density_generators;}
 int density_dimension=image.rows.size();for(int i=0;i<r;++i)image.insert(physical.reduce(integrator.endpoint.finite_part(i,ZR(1))),image.rows.size());int image_dimension=image.rows.size();
 auto convert=[&](C c){auto values=image.solve(std::move(c),image_dimension);C row;for(int i=0;i<image_dimension;++i)if(values[i])row["u:"+std::to_string(i)]=values[i];return row;};
 Quotient relations;int unrepresented_relations=0;for(auto&gjson:cfg["reference_seeds"]){auto g=readrow(gjson);std::vector<ZR>v(r);C boundary;for(int i=0;i<r;++i){v[i]=v[i]+g[i].diff();if(g[i].zero())continue;axpy(boundary,integrator.endpoint.finite_part(i,g[i]),1);for(int j=i;j<r;++j)if(!A[i][j].zero())v[j]=v[j]+g[i]*A[i][j];}C c=integrator.raw(std::move(v));axpy(c,boundary,1);c=physical.reduce(std::move(c));try{relations.insert(convert(std::move(c)));}catch(const std::exception&){++unrepresented_relations;}}
 auto relation_seconds=seconds(start);json unresolved=json::array();std::map<std::string,C>coordinates;for(auto it=cfg["rows"].begin();it!=cfg["rows"].end();++it){try{coordinates[it.key()]=relations.reduce(convert(raw_image(readrow(it.value()))));}catch(const std::exception&){unresolved.push_back(it.key());}}
 auto basis=cfg["basis"].get<std::vector<std::string>>();Span span;bool independent=true;for(int i=0;i<int(basis.size());++i){auto name=basis[i];if(!coordinates.count(name)&&name.rfind("Bz",0)==0){auto row=readrow(cfg["rows"].at(parent_j(name)));C c;for(int j=0;j<r;++j)axpy(c,integrator.endpoint.finite_part(j,row[j]),1);coordinates[name]=relations.reduce(convert(physical.reduce(std::move(c))));}if(!coordinates.count(name)||!span.insert(coordinates.at(name),i))independent=false;}
 json values=json::object();for(auto&nu:cfg["targets"]){auto name=label(nu.get<Nu>());if(!coordinates.count(name))continue;try{auto v=span.solve(coordinates.at(name),basis.size());json row=json::object();for(size_t i=0;i<v.size();++i)if(v[i])row[basis[i]]=v[i];values[name]=row;}catch(const std::exception&){unresolved.push_back(name);}}
 json out={{"seed_source",seeds},{"density_generators",density_generators},{"density_image_dimension",density_dimension},{"image_dimension_with_boundary",image_dimension},{"local_analytic_rows",physical.nonzero_rows},{"local_analytic_rank",physical.rows.size()},{"local_analytic_columns",physical.submitted_columns.size()},{"global_nonzero_rows",relations.nonzero_rows},{"global_rank",relations.rows.size()},{"global_columns",relations.submitted_columns.size()},{"global_nnz",relations.submitted_nonzeros},{"unrepresented_relations",unrepresented_relations},{"basis_independent",independent},{"unresolved",unresolved},{"reductions",values},{"relation_seconds",relation_seconds},{"total_seconds",seconds(start)}};save_json(output,out);std::cerr<<"image dim="<<image_dimension<<" relations="<<relations.rows.size()<<" unrepresented="<<unrepresented_relations<<" unresolved="<<unresolved.size()<<" seconds="<<seconds(start)<<"\n";
}
int main(int argc,char**argv){try{if(argc<4)throw std::runtime_error("experiment snapshot REQUEST OUTPUT | reduce SNAPSHOT OUTPUT reference|SEEDS");std::string mode=argv[1];if(mode=="snapshot")snapshot(argv[2],argv[3]);else if(mode=="image"&&argc==5)image_reduce(argv[2],argv[3],argv[4]);else if(mode=="reduce"&&argc==5)reduce_snapshot(argv[2],argv[3],argv[4]);else throw std::runtime_error("invalid experiment arguments");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
